// Per-user chat preferences including visible channels (via channel_categories), pinned channels, per-category limits, and sidebar display state. Only channels present in channel_categories are visible in sidebar. Order is derived from channel.updated_at (most recent first).
type ChatUserChatConfig struct {
	ID             dbuuid.UUID `json:"id"`
	OrganizationID dbuuid.UUID `json:"organization_id"`
	EmployeeID     dbuuid.UUID `json:"employee_id"`
	// JSONB mapping of channel_id to category. Presence in this map makes channel visible in sidebar. Example: {"uuid-1": "channels", "uuid-2": "direct_messages"}. Categories: channels (public/private channels), direct_messages (1-on-1 DMs), archived (archived channels). Order within category determined by channel.updated_at DESC.
	ChannelCategories []byte `json:"channel_categories"`
	// JSONB object defining max visible channels per category. Example: {"channels": 30, "direct_messages": 20, "archived": 10}. When category exceeds limit, oldest channels (by updated_at) are automatically removed from channel_categories.
	CategoryLimits []byte `json:"category_limits"`
	// Array of pinned channel IDs (subset of channel_categories keys). Pinned channels appear at top within their category, ordered by position in this array. Non-pinned channels follow, ordered by updated_at DESC.
	PinnedChannelIds []dbuuid.UUID `json:"pinned_channel_ids"`
	// JSONB object tracking collapsed state of sidebar categories. Example: {"channels": false, "direct_messages": false}.
	SidebarCategoryCollapsed []byte             `json:"sidebar_category_collapsed"`
	UpdatedAt                pgtype.Timestamptz `json:"updated_at"`
}

