// Task project container with configurable states and task levels. Projects group related tasks and define workflow.
type CollaborationProject struct {
	ID             dbuuid.UUID `json:"id"`
	OrganizationID dbuuid.UUID `json:"organization_id"`
	Name           string      `json:"name"`
	// Short uppercase identifier (1-10 chars) for task prefixes. Example: "PROJ" creates tasks PROJ-1, PROJ-2. MUST be unique per organization.
	Key         string      `json:"key"`
	Description pgtype.Text `json:"description"`
	// Atomic counter for task identifier generation. Incremented on each task creation.
	NextTaskNumber int32 `json:"next_task_number"`
	// Project visibility: public (all org members can view), private (explicit grants only). MUST align with backend constants in internal/collaboration/constants.go.
	Visibility        string             `json:"visibility"`
	IsArchived        bool               `json:"is_archived"`
	OwnerEmployeeID   dbuuid.UUID        `json:"owner_employee_id"`
	MemberCount       int32              `json:"member_count"`
	TaskCount         int32              `json:"task_count"`
	UpdatedAt         pgtype.Timestamptz `json:"updated_at"`
	CollaborationMode string             `json:"collaboration_mode"`
}

func (s *CollaborationProject) TableName() string {
	return "collaboration.project"
}

func (s *CollaborationProject) Fields() ([]string, []any) {
	return []string{
			"id",
			"organization_id",
			"name",
			"key",
			"description",
			"next_task_number",
			"visibility",
			"is_archived",
			"owner_employee_id",
			"member_count",
			"task_count",
			"updated_at",
			"collaboration_mode",
		}, []any{
			&s.ID,
			&s.OrganizationID,
			&s.Name,
			&s.Key,
			&s.Description,
			&s.NextTaskNumber,
			&s.Visibility,
			&s.IsArchived,
			&s.OwnerEmployeeID,
			&s.MemberCount,
			&s.TaskCount,
			&s.UpdatedAt,
			&s.CollaborationMode,
		}
}

func (s *CollaborationProject) FieldsMap() map[string]any {
	return map[string]any{
		"id":                 &s.ID,
		"organization_id":    &s.OrganizationID,
		"name":               &s.Name,
		"key":                &s.Key,
		"description":        &s.Description,
		"next_task_number":   &s.NextTaskNumber,
		"visibility":         &s.Visibility,
		"is_archived":        &s.IsArchived,
		"owner_employee_id":  &s.OwnerEmployeeID,
		"member_count":       &s.MemberCount,
		"task_count":         &s.TaskCount,
		"updated_at":         &s.UpdatedAt,
		"collaboration_mode": &s.CollaborationMode,
	}
}

