// Core task entity with hierarchical nesting, workflow states, and cross-domain integrations to chat (comments), docs (description), and files (attachments).
type CollaborationTask struct {
	ID             dbuuid.UUID `json:"id"`
	OrganizationID dbuuid.UUID `json:"organization_id"`
	ProjectID      dbuuid.UUID `json:"project_id"`
	// Human-readable task identifier: {project_key}-{number}. Example: PROJ-123. Unique within project.
	Identifier   string          `json:"identifier"`
	Title        string          `json:"title"`
	ParentTaskID dbuuid.NullUUID `json:"parent_task_id"`
	Depth        int16           `json:"depth"`
	// Materialized path array of ancestor task IDs from root to parent. Enables efficient subtree queries.
	Path           []dbuuid.UUID  `json:"path"`
	LevelID        dbuuid.UUID    `json:"level_id"`
	StateID        dbuuid.UUID    `json:"state_id"`
	StartDate      pgtype.Date    `json:"start_date"`
	DueDate        pgtype.Date    `json:"due_date"`
	EstimatedHours pgtype.Numeric `json:"estimated_hours"`
	// Chat channel for task comments and discussion. Auto-created on task creation with channel_type=project_ticket_thread.
	ChannelID dbuuid.NullUUID `json:"channel_id"`
	// Linked document for rich task description with versioning and comments. Auto-created on task creation with document_type=task_description. These documents should NOT appear in workspace docs list.
	DescriptionDocumentID dbuuid.NullUUID `json:"description_document_id"`
	// Array of file UUIDs from files.file_metadata. Managed via Files API with upload_context=project.
	FileIds            []dbuuid.UUID      `json:"file_ids"`
	ReporterEmployeeID dbuuid.UUID        `json:"reporter_employee_id"`
	ChildCount         int32              `json:"child_count"`
	CommentCount       int32              `json:"comment_count"`
	IsDeleted          bool               `json:"is_deleted"`
	UpdatedAt          pgtype.Timestamptz `json:"updated_at"`
	TaskKind           string             `json:"task_kind"`
	RitualDefinitionID dbuuid.NullUUID    `json:"ritual_definition_id"`
	ScheduledDate      pgtype.Date        `json:"scheduled_date"`
	CompletionDeadline pgtype.Timestamptz `json:"completion_deadline"`
	SkipReason         pgtype.Text        `json:"skip_reason"`
	DetachedFromRitual bool               `json:"detached_from_ritual"`
}

