// Reference-table registry of backend LISTEN connections for instance-scoped notification topics. Used for operational debugging and stale listener cleanup.
type NotificationActiveListener struct {
	InstanceID string `json:"instance_id"`
	// PostgreSQL LISTEN topic currently owned by the backend instance, e.g. instance_backend_pod_abc_notifications.
	ListenTopic string `json:"listen_topic"`
	// Backend PostgreSQL session PID for the dedicated LISTEN connection when available.
	BackendPid  pgtype.Int4        `json:"backend_pid"`
	ConnectedAt pgtype.Timestamptz `json:"connected_at"`
	// Updated periodically by the backend listener goroutine. Stale entries indicate the LISTEN loop likely died or the instance crashed.
	LastHeartbeat  pgtype.Timestamptz `json:"last_heartbeat"`
	ListenerStatus string             `json:"listener_status"`
	// Status of the consumeNotifications goroutine: starting, running (processing NOTIFYs), reconnecting (re-establishing connection), stopped (exited). If this is stopped while listener_status=active, the listener heartbeat is alive but notification delivery is broken.
	ConsumerStatus string `json:"consumer_status"`
	// Last time the consumer goroutine successfully processed a NOTIFY event. A large gap between this and last_heartbeat indicates the consumer is stuck or dead.
	ConsumerLastActiveAt pgtype.Timestamptz `json:"consumer_last_active_at"`
	// Number of times the LISTEN connection was re-established after an unexpected disconnection. Non-zero indicates instability.
	ReconnectCount int32 `json:"reconnect_count"`
	// Most recent error encountered by the consumer goroutine or reconnect logic. Truncated to 500 chars.
	LastError pgtype.Text `json:"last_error"`
	// When last_error occurred.
	LastErrorAt pgtype.Timestamptz `json:"last_error_at"`
}

