// Links notifications to employees with delivery and read tracking
type NotificationNotificationRecipient struct {
	ID             dbuuid.UUID `json:"id"`
	NotificationID dbuuid.UUID `json:"notification_id"`
	EmployeeID     dbuuid.UUID `json:"employee_id"`
	OrganizationID dbuuid.UUID `json:"organization_id"`
	// Whether the notification has been read by the employee. When set to true, delivery_status is automatically updated to delivered.
	ReadStatus pgtype.Bool        `json:"read_status"`
	ReadAt     pgtype.Timestamptz `json:"read_at"`
	// pending = awaiting delivery, delivered = sent via SSE or fallback, failed = all delivery attempts failed. Auto-updated to delivered when notification is marked as read.
	DeliveryStatus    pgtype.Text        `json:"delivery_status"`
	DeliveredAt       pgtype.Timestamptz `json:"delivered_at"`
	DeliveryAttempts  pgtype.Int2        `json:"delivery_attempts"`
	LastDeliveryError pgtype.Text        `json:"last_delivery_error"`
	// How recipient was targeted: individual (direct to employee_id) or department (resolved from department membership)
	RecipientType string `json:"recipient_type"`
	// If sent to department, stores resolved department IDs for audit trail
	TargetDepartmentIds []dbuuid.UUID `json:"target_department_ids"`
	// Authoritative unread signal. pending = not yet acknowledged, acknowledged = destination opened or explicitly acknowledged. Frontend unread counts MUST derive from this field.
	AcknowledgementStatus string             `json:"acknowledgement_status"`
	AcknowledgedAt        pgtype.Timestamptz `json:"acknowledged_at"`
	// How the notification was acknowledged: destination_open (user navigated to the linked resource) or explicit_ack (user dismissed via explicit action). Popup display alone does NOT acknowledge.
	AcknowledgementAction pgtype.Text `json:"acknowledgement_action"`
	// Latest offline delivery outcome summary: not_applicable, queued, sent, skipped, failed.
	FallbackStatus string `json:"fallback_status"`
	// Why fallback was queued, skipped, sent, or failed. Values: live_only_policy, no_push_target, recipient_ineligible, recipient_online, suppressed_by_preference, sse_receipt_confirmed, acknowledged_before_fallback, connection_unresponsive, delivery_error.
	FallbackReason    pgtype.Text        `json:"fallback_reason"`
	FallbackUpdatedAt pgtype.Timestamptz `json:"fallback_updated_at"`
	UpdatedAt         pgtype.Timestamptz `json:"updated_at"`
	// Deadline for delayed rescue push when SSE delivery is ambiguous. NULL when no rescue job is queued.
	FallbackDueAt pgtype.Timestamptz `json:"fallback_due_at"`
}

